const $=id=>document.getElementById(id),canvas=$('canvas'),ctx=canvas.getContext('2d');
let mode=0,distance=0,last=0,elapsed=0,paused=false,playing=false,jump=0,vy=0,objects=[],spawn=0,invincible=0,toastUntil=0,stroke=0,sound=false,audio,raf;
const jokes=['“Một câu cuối thôi…”','Cuộc họp đã kéo dài. Đường chạy thì có đích.','Không cần giải trình pha vừa rồi. Chạy tiếp thôi.'];
function beep(freq=440,time=.08){if(!sound)return;audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=freq;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+time);o.start();o.stop(audio.currentTime+time)}
$('sound').onclick=()=>{sound=!sound;$('sound').textContent=`Âm thanh: ${sound?'bật':'tắt'} ♫`;beep()};
function toast(t,seconds=3){$('bubble').textContent=t;toastUntil=elapsed+seconds;$('bubble').hidden=false}
function resize(){const r=canvas.getBoundingClientRect();canvas.width=r.width*devicePixelRatio;canvas.height=r.height*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0)}
addEventListener('resize',resize);
function act(){if(!playing||paused)return;if(mode===1){stroke=Math.min(1,stroke+.35);beep(330)}else if(jump===0){vy=440;jump=.01;beep(520)}}
$('action').onclick=act;canvas.addEventListener('pointerdown',act);addEventListener('keydown',e=>{if(e.code==='Space'&&playing){e.preventDefault();if(!e.repeat)act()}});
$('pause').onclick=()=>{if(!playing||!$('transition').hidden)return;paused=!paused;$('pause').textContent=paused?'Tiếp tục ▶':'Tạm dừng Ⅱ'};
function transition(title,text,button,next){paused=true;$('transition').hidden=false;$('transitionTitle').textContent=title;$('transitionText').textContent=text;$('continue').textContent=button;$('continue').onclick=()=>{$('transition').hidden=true;paused=false;next()}}
function start(){cancelAnimationFrame(raf);$('intro').hidden=true;$('finish').hidden=true;$('game').hidden=false;$('gift').hidden=true;mode=0;distance=elapsed=jump=vy=spawn=invincible=stroke=0;objects=[];playing=true;paused=false;last=0;$('transition').hidden=true;$('pause').textContent='Tạm dừng Ⅱ';setChapter();resize();toast('Kế hoạch: đón sinh nhật. Trạng thái: chờ phản biện.',4);raf=requestAnimationFrame(frame);window.scrollTo({top:0,behavior:'smooth'})}
$('start').onclick=start;$('replay').onclick=()=>{$('openGift').hidden=false;$('checklist').hidden=true;start()};
function setChapter(){const names=['Cuộc họp chưa chịu kết thúc.','Phương án B: chèo tới sinh nhật.','Kiêu hãnh & một chiếc mái chèo.'];$('chapter').textContent=`CHƯƠNG 0${mode+1} / THE BIRTHDAY ESCAPE`;$('chapterTitle').textContent=names[mode];$('action').textContent=mode===1?'Chèo thôi ≋':'Nhảy ↑';$('instruction').textContent=mode===1?'Chạm để chèo nhanh hơn. Thuyền vẫn tự trôi nếu Vy muốn nghỉ.':'Chạm màn hình hoặc nhấn Space để nhảy.'}
function frame(t){if(!playing)return;const dt=last?Math.min((t-last)/1000,.04):0;last=t;if(!paused){elapsed+=dt;distance+=dt*(mode===1?25+stroke*18:30);stroke=Math.max(0,stroke-dt*.3);invincible=Math.max(0,invincible-dt);if(jump>0){jump+=vy*dt;vy-=1100*dt;if(jump<=0){jump=vy=0}}spawn-=dt;if(spawn<=0){objects.push({x:canvas.clientWidth+40,type:Math.floor(Math.random()*3),hit:false});spawn=2.3+Math.random()*.7}objects.forEach(o=>{o.x-=dt*(mode===1?160:220);if(!o.hit&&o.x<120&&o.x>65){o.hit=true;if(mode===1){beep(660);if(Math.random()>.6)toast('Lên thuyền rồi. Xin đừng gửi thêm slide.')}else if(jump<48&&invincible===0){invincible=1.3;beep(160);toast(mode===2?'Tên là khôn. Thời điểm xuất hiện thì cần xem lại.':jokes[2])}}});objects=objects.filter(o=>o.x>-90);if(elapsed>toastUntil)$('bubble').hidden=true;
if(mode===0&&distance>=540){distance=540;transition('“Hồi chiều trời mưa…”','Đường chạy đã chuyển thành đường thủy. Trạm tiếp tế gửi tới một chiếc thuyền: PHƯƠNG ÁN B.','Nhận thuyền & mái chèo ↗',()=>{mode=1;objects=[];setChapter();toast('Mái chèo: “Kế hoạch đã chỉnh sửa”. Không ngờ có ngày dùng để quạt nước.',5)})}
if(mode===1&&distance>=1080){distance=1080;transition('Răng khôn tham gia cuộc đua.','Kỹ năng đặc biệt: chọn đúng lúc để gây chuyện. Vy đã lên bờ — chặng cuối tới rạp phim!','Đã tiễn một chiếc răng. Chạy tiếp ↗',()=>{mode=2;objects=[];setChapter();toast('Tâm trạng sau nhổ răng: “Mình ổn. Má mình có ý kiến riêng.”',5)})}
if(distance>=1710){distance=1710;finish();return}}
draw();$('distance').textContent=Math.floor(distance).toLocaleString('vi-VN')+' m';$('progress').style.width=distance/1710*100+'%';raf=requestAnimationFrame(frame)}
function draw(){const w=canvas.clientWidth,h=canvas.clientHeight,y=h-75;ctx.clearRect(0,0,w,h);let grad=ctx.createLinearGradient(0,0,0,h);grad.addColorStop(0,mode===2?'#293c49':'#172c40');grad.addColorStop(1,mode===1?'#47757b':'#31515a');ctx.fillStyle=grad;ctx.fillRect(0,0,w,h);ctx.fillStyle='#e6d6af';ctx.beginPath();ctx.arc(w-75,70,30,0,Math.PI*2);ctx.fill();for(let i=0;i<18;i++){let x=((i*77-elapsed*14)%(w+100)+w+100)%(w+100)-70;let bh=65+(i*37%90);ctx.fillStyle=i%2?'#132d3c':'#1c3744';ctx.fillRect(x,y-bh,56,bh);ctx.fillStyle='#dcb87866';for(let a=0;a<3;a++)for(let b=0;b<3;b++)ctx.fillRect(x+9+a*14,y-bh+15+b*20,4,7)}ctx.fillStyle=mode===1?'#285c70':'#142a35';ctx.fillRect(0,y,w,75);ctx.strokeStyle=mode===1?'#9ac3bf66':'#dfb77c66';ctx.lineWidth=2;for(let i=0;i<12;i++){let x=(i*100-elapsed*(mode===1?80:180))%(w+100);ctx.beginPath();ctx.moveTo(x,y+35);ctx.lineTo(x+45,y+35+(mode===1?Math.sin(elapsed*3+i)*3:0));ctx.stroke()}if(mode===1){ctx.strokeStyle='#b8d0d566';for(let i=0;i<55;i++){let x=(i*53+elapsed*110)%w,ry=(i*37+elapsed*240)%h;ctx.beginPath();ctx.moveTo(x,ry);ctx.lineTo(x-7,ry+17);ctx.stroke()}}
ctx.textAlign='center';ctx.font='52px "Segoe UI Emoji",sans-serif';if(invincible===0||Math.floor(elapsed*12)%2===0){ctx.save();ctx.translate(95,y-8-jump);if(mode===1){ctx.font='65px "Segoe UI Emoji"';ctx.fillText('🛶',0,Math.sin(elapsed*4)*4);ctx.font='30px "Segoe UI Emoji"';ctx.fillText('👩',0,-27)}else{ctx.scale(-1,1);ctx.fillText('🏃‍♀️',0,0)}ctx.restore()}
objects.forEach(o=>{const icons=mode===0?['📑','⏰','✈️']:mode===1?['📄','⏰','🌊']:['🦷','🦷','🎟️'];ctx.font='37px "Segoe UI Emoji"';ctx.fillText(icons[o.type],o.x,y-4);ctx.fillStyle='#eadfcb';ctx.font='9px "Be Vietnam Pro",sans-serif';const labels=mode===0?['Thêm một slide','Họp 5 phút nữa','Chỉnh kế hoạch']:mode===1?['Slide nổi','Vẫn 5 phút nữa','Sóng nhẹ thôi']:['Răng “khôn”','Sai thời điểm','Vé vào rạp'];ctx.fillText(labels[o.type],o.x,y+19)});ctx.textAlign='left';ctx.fillStyle='#dfb77c';ctx.font='10px "Be Vietnam Pro",sans-serif';ctx.fillText(mode===1?'PHƯƠNG ÁN B · CHÈO ĐỀU TAY':mode===2?'ĐÍCH ĐẾN: SUẤT CHIẾU SINH NHẬT':'VĂN PHÒNG → MỘT BUỔI TỐI TỰ DO',18,h-15)}
function finish(){playing=false;beep(784,.4);$('game').hidden=true;$('finish').hidden=false;window.scrollTo({top:0,behavior:'smooth'});for(let i=0;i<45;i++){let el=document.createElement('i');el.style.cssText=`position:fixed;pointer-events:none;width:5px;height:9px;background:${i%2?'#dfb77c':'#efe6d5'};left:${Math.random()*100}vw;top:-15px;z-index:8;`;document.body.append(el);el.animate([{transform:'translateY(-10px) rotate(0)',opacity:1},{transform:`translateY(105vh) rotate(${Math.random()*800}deg)`,opacity:0}],{duration:2500+Math.random()*2000,delay:Math.random()*800}).onfinish=()=>el.remove()}}
$('openGift').onclick=()=>{$('gift').hidden=false;$('openGift').hidden=true;$('gift').scrollIntoView({behavior:'smooth',block:'start'})};$('plan').onclick=()=>{$('checklist').hidden=!$('checklist').hidden};
// Optional personal portrait. Keep the designed monogram when no photo is supplied.
const personalPhoto=new URLSearchParams(location.search).get('photo');
if(personalPhoto){const portrait=new Image();portrait.alt='Thanh Vy trong suất chiếu sinh nhật';portrait.onload=()=>{$('portrait').replaceChildren(portrait)};portrait.src=personalPhoto}
